@ ===========================================================================
@  mvdk_music_data.s  -  music data, ROM 0x08DDD85C-0x08F8A0CC
@    0x08DDD85C song count + song table (70)      0x08DDDBA8 PCM (124 blocks, mvdk_music_pcm.bin)
@    0x08EFF83C sample headers (328)              0x08F035BC instruments (156)
@    0x08F0F64C modules (70), packed patterns with every row decoded in the comment:
@               channel:note instrument vVolumeColumn pPanColumn effect ("..." = not in the cell)
@ ===========================================================================
	.include "mvdk_sound.inc"

	.macro SONG module, vol, v0, v1, v2, flag
	.word \module
	.hword \vol
	.byte \v0, \v1, \v2, \flag
	.hword 0
	.endm
	.macro SMP len, ls, ll, vol, amp, fine, type, pan, rel
	.word \len, \ls, \ll
	.byte \vol, \amp, \fine, \type, \pan, \rel
	.endm
	.section .snd_music, "a", %progbits
	.global musSongCount, musSongTable, musInstruments
musSongCount: .hword 70, 0 @ 0x08DDD85C
@ SongEntry: module, volume (x/128), mixing voices taken by SFX voices 0..2 (1-based, 0 = 8-n), flag (not read by the driver)
